"""What is said and shown: scene list per variant. Texts are spoken; cue functions place the animation
of a scene relative to the start times of its sentences (c[i], seconds from the start of the scene)."""
from . import scenes as S
from . import scenes2 as S2

CHIP_BOX = "left:96px;top:{}px;font-size:{}px;font-weight:700;padding:14px 26px;border-radius:14px;background:rgba(8,11,16,.92);border:2px solid {};color:{}"


def short(data):
    R, T = data["results"], data["results"]["timing"]
    rows = [("$ flow/run.sh config.json", "cmd", None), ("Magic DRC errors ............... ", "", "0"), ("KLayout DRC errors ............. ", "", "0"),
            ("Antenna violations ............. ", "", "0"), ("Setup / hold violations ........ ", "", "0 / 0"), ("", "", None),
            ("$ python -m signoff.run_chip", "cmd", None), (f"Devices: {R['lvs_devices']:,} | {R['lvs_devices']:,}", "dim", None),
            (f"Nets:    {R['lvs_nets']:,}  | {R['lvs_nets']:,}", "dim", None), ("Final result: ", "", "Circuits match uniquely.")]
    return [
        dict(fn=S.title, text=["""This is a six transistor SRAM: 64 words of 32 bits, on SkyWater's open source 130 nm process, SKY130.
             The cell array is custom layout, generated by Python code, and everything is checked with open tools."""]),
        dict(fn=S.cell, args=dict(q=lambda c, D: dict(cross=1.3, states=2.7, pg=min(c[1] - 2.6, 4.6), read=c[2] - 0.15, wlon=c[2] + 0.35, flow=c[2] + 0.8,
                                                      flowdur=c[3] - c[2] - 1.3, bump=c[2] + 2.0, rule1=c[2] + 0.5, write=c[3] - 0.1, fight=c[3] + 0.7,
                                                      fightdur=min(2.8, D - (c[3] + 0.7) - 0.6), rule2=c[3] + 0.6, both=D - 1.5)),
             text=["""Each bit lives in two inverters connected in a loop, and two pass gates connect it to the bit lines.
             Sizing the cell is a tug of war. The pull down must beat the pass gate, or a read flips the cell.
             And the pass gate must beat the pull up, or a write fails."""]),
        dict(fn=S.butterfly, args=dict(q=lambda c, D: dict(curves=0.7, square=2.1, read=c[0] + 4.2, worst=c[1] + 0.1)),
             text=[f"""I chose the sizes from butterfly curves over all process, voltage and temperature corners.
             The worst case read margin is {R['bitcell']['read_worst'] * 1000:.0f} millivolts,
             and a thousand Monte Carlo samples per corner show no failures."""]),
        dict(fn=S.layers, args=dict(q=lambda c, D: dict(l1=0.5, l2=1.3, l3=2.1, l4=2.9, l5=3.6, box=0.9, cmp=c[1] - 0.1)),
             text=["""The cell is drawn with the ordinary logic design rules, so the standard rule decks apply without any waivers.
             That costs area: it is about twice the size of the foundry's own cell."""]),
        dict(fn=S.zoom, args=dict(
            way=lambda c, D: [(0.5, 0), (c[1] - 0.2, 1), (D - 1.2, 5)],
            overlays=lambda c, D: [(c[0] + 0.5, "mirrored neighbours share their contacts", CHIP_BOX.format(880, 30, "#e3b341", "#e3b341"), c[1] - 0.2),
                                   (c[1] + 0.6, f"64 × 32 cells · {R['array_mosfets']:,} transistors", CHIP_BOX.format(880, 34, "#58a6ff", "#e6edf3"), None)]),
             text=[f"""Mirrored neighbours share their contacts. Sixty four rows of thirty two cells make the array: {R['array_mosfets']:,} transistors."""]),
        dict(fn=S.timing, args=dict(q=lambda c, D: dict(draw=0.8, drawdur=c[2] - 0.6, strike=c[0] + 0.7, strike_out=c[2] - 0.3, hi=c[2] + 0.4,
                                                        lo=c[2] + 2.6, slow=c[3] + 0.1)),
             text=["""Around the array there is no sense amplifier, and no self timed pulse. The bit lines swing from rail to rail, and a plain inverter senses them.
             The bit lines precharge while the clock is high, and the access happens while it is low. If a phase is too short, you slow the clock down."""]),
        dict(fn=S.chip, args=dict(q=lambda c, D: dict(array=0.9, dec=1.9, col=2.8, tools=1.1, size=c[1] + 0.1)),
             text=[f"""That periphery is ordinary Verilog, placed and routed as standard cells next to the array. The complete memory measures
             {R['die_w']:g} by {R['die_h']:g} µm."""]),
        dict(fn=S.signoff, args=dict(rows=rows, stamp=f"0 violations\n{R['lvs_devices']:,} devices\nmatch", q=lambda c, D: dict(start=0.6, span=D - 3.4, stamp=D - 2.4)),
             text=["""The final layout has zero design rule violations in two independent checkers, and it matches its netlist transistor by transistor."""]),
        dict(fn=S.waves, args=dict(q=lambda c, D: dict(draw=0.8, drawdur=c[1] + 1.2, tcq=c[1] + 0.3, tcq_ss=D - 2.6)),
             text=[f"""In SPICE on the extracted layout, a word is written and read back. The data is out {T['tt']['t_cq_max']:.1f} nanoseconds after the clock edge,
             and {T['ss']['t_cq_max']:.1f} nanoseconds at the slow corner."""]),
        dict(fn=S.wrap, args=dict(items=["GDS, LEF, Liberty for three corners", "Verilog model and SPICE netlists", "March C- self-test, routed with the macro",
                                         "Every step reproducible from code"],
                                  warn=["No silicon: nothing here has been fabricated or measured."],
                                  url="github.com/Melihakbulut221/sky130-sram-64x32",
                                  q=lambda c, D: dict(items=0.5, istep=0.45, warn=c[1] - 0.1, url=c[2] + 0.2)),
             text=["""It comes with timing libraries, a simulation model and a self test. What it does not have yet is silicon: nothing here has been fabricated.
             The full video, and all of the code, are on GitHub."""]),
    ]


def full(data):
    """The complete video. The narration is the text of video/script.py, step by step; several steps that
    share one picture there are one animated scene here."""
    from video import script as L
    R, T = data["results"], data["results"]["timing"]
    tx = [t for _, t in L.STEPS]
    URL = "github.com/Melihakbulut221/sky130-sram-64x32"
    arr_rows = [("$ python -m signoff.run_macro", "cmd", None), ("Magic 8.3   drc(full) .......... ", "", "0"), ("KLayout     sky130A_mr.drc ..... ", "", "0"),
                ("", "", None), ("Netgen 1.5  layout vs. schematic", "dim", None),
                (f"Devices: {R['array_lvs_devices']:,} | {R['array_lvs_devices']:,}", "dim", None), (f"Nets:    {R['array_lvs_nets']:,}  | {R['array_lvs_nets']:,}", "dim", None),
                ("Final result: ", "", "Circuits match uniquely.")]
    chip_rows = [("$ flow/run.sh config.json", "cmd", None), ("Magic DRC errors ............... ", "", "0"), ("KLayout DRC errors ............. ", "", "0"),
                 ("Antenna violations ............. ", "", "0"), ("Setup / hold violations ........ ", "", "0 / 0"), ("", "", None),
                 ("$ python -m signoff.run_chip", "cmd", None), (f"Devices: {R['lvs_devices']:,} | {R['lvs_devices']:,}", "dim", None),
                 (f"Nets:    {R['lvs_nets']:,}  | {R['lvs_nets']:,}", "dim", None), ("Final result: ", "", "Circuits match uniquely.")]
    return [
        # ---- intro
        dict(fn=S.title, text=[tx[0]]),
        dict(fn=S2.stats, args=dict(q=lambda c, D: dict(hero=c[1] + 0.4, array=c[2] + 0.2, peri=c[3] + 0.2, rows=[c[4] + 0.4, c[4] + 3.4, c[4] + 6.4], warn=c[5] + 0.2)),
             text=[tx[1]]),
        # ---- the cell: hold, read, write on one schematic
        dict(fn=S.cell, args=dict(q=lambda c, D: dict(cross=1.3, states=c[1] + 0.3, pg=c[2] + 0.2, read=c[3] - 0.15, wlon=c[3] + 2.8, flow=c[4] + 0.2,
                                                      flowdur=c[7] - c[4] - 0.6, bump=c[5] + 1.6, rule1=c[7] + 0.6, write=c[8] - 0.1, fight=c[9] + 1.8,
                                                      fightdur=c[10] - c[9] - 1.2, rule2=c[10] + 0.5, both=c[11] + 0.2)),
             text=[tx[2], tx[3], tx[4]]),
        dict(fn=S.butterfly, args=dict(q=lambda c, D: dict(curves=c[1] + 0.2, square=c[2] - 1.2, read=c[3] - 0.1, worst=c[3] + 3.0)), text=[tx[5]]),
        dict(fn=S2.bars, args=dict(q=lambda c, D: dict(read=0.9, write=c[1] + 2.8, chosen=c[2] + 0.2, hvt=c[2] + 5.0)), text=[tx[6]]),
        dict(fn=S2.hist, args=dict(q=lambda c, D: dict(tt=0.8, worst=c[1] + 0.3, fail=c[1] + 5.0, sigma=c[1] + 6.2, note=c[2] + 0.2)), text=[tx[7]]),
        # ---- the layout
        dict(fn=S.layers, args=dict(q=lambda c, D: {"l1": 0.5, "box": c[1] + 0.2, "k-n": c[2] + 0.3, "k-n_out": c[4] - 0.2, "k-p": c[3] + 0.3, "k-p_out": c[4] - 0.2,
                                                    "l2": c[4] - 0.1, "k-poly": c[5] + 0.3, "k-poly_out": c[7] - 0.2, "l3": c[7] + 0.2, "k-x": c[10] + 2.2,
                                                    "k-x_out": c[11] - 0.4, "cmp": c[11] - 0.1, "cmp_out": c[12] - 0.25, "l4": c[12], "k-wl": c[12] + 0.9,
                                                    "l5": c[13] - 0.1, "k-bl": c[13] + 2.6}),
             text=[tx[8], tx[9], tx[10], tx[11]]),
        dict(fn=S2.codepic, args=dict(path="sram/cells.py", start="    def diff(X, Y):", n=5, fs=24, kicker="The layout", ttl="The layout is a Python function",
                                      cards=[("Drawn once, placed twice", "The cell is point symmetric: every shape is written once, and the code mirrors it."),
                                             ("Parameters in, layout out", "Change a transistor width: layout, DRC, LVS and extraction run again.")],
                                      q=lambda c, D: dict(call1=c[1] + 1.2, hl=c[2] - 0.2, call2=c[2] + 3.6, cards=[c[2] + 0.4, D - 2.6])),
             text=[tx[12]]),
        dict(fn=S.zoom, args=dict(
            way=lambda c, D: [(0.5, 0), (c[0] + 5.5, 1), (c[1] + 0.4, 1), (c[1] + 3.6, 3), (c[2] - 0.4, 3), (c[2] + 4.2, 5)],
            overlays=lambda c, D: [(c[0] + 0.5, "mirrored neighbours share their contacts", CHIP_BOX.format(880, 30, "#e3b341", "#e3b341"), c[1] - 0.2),
                                   (c[1] + 2.4, "every 16 rows: a strap row with well taps and power rails", CHIP_BOX.format(880, 30, "#39c5cf", "#39c5cf"), c[2] - 0.3),
                                   (c[2] + 2.0, f"64 × 32 cells · {R['array_mosfets']:,} transistors · 158 × 66 µm", CHIP_BOX.format(880, 34, "#58a6ff", "#e6edf3"), None),
                                   (c[3] + 0.4, "word lines: left · bit lines: bottom · power: metal 4 straps", CHIP_BOX.format(806, 28, "#2a3442", "#8b96a5"), None)]),
             text=[tx[13], tx[14]]),
        dict(fn=S.signoff, args=dict(rows=arr_rows, kicker="The layout", ttl="Sign-off of the array", stamp="array\n0 violations\nLVS match", th=560,
                                     q=lambda c, D: dict(start=0.6, span=D - 4.2, stamp=D - 3.0)),
             text=[tx[15]]),
        # ---- the periphery
        dict(fn=S2.arch, args=dict(q=lambda c, D: dict(arr=0.6, dec=c[0] + 4.2, col=c[0] + 6.0, rest=c[0] + 8.6, usual=c[1] + 0.8, boring=c[2] + 2.0)), text=[tx[16]]),
        dict(fn=S.timing, args=dict(q=lambda c, D: dict(draw=0.8, drawdur=c[2] - 0.6, strike=c[1] - 0.8, strike_out=c[2] - 0.3, hi=c[2] + 0.4, lo=c[3] + 0.4, slow=c[4] + 0.1)),
             text=[tx[17]]),
        dict(fn=S2.tristate, args=dict(q=lambda c, D: dict(pre=c[1] + 0.1, write=c[1] + 1.9, keep=c[1] + 4.8, static=c[2] + 0.6, stop=c[3] + 0.1)), text=[tx[18]]),
        dict(fn=S2.race, args=dict(q=lambda c, D: dict(edge=0.9, ff=c[0] + 3.8, wl=c[0] + 5.4, danger=c[0] + 6.6, fix=c[1] + 0.3)), text=[tx[19]]),
        # ---- RTL to GDS
        dict(fn=S.chip, args=dict(q=lambda c, D: dict(tools=c[0] + 3.2, array=c[0] + 7.6, dec=c[1] + 0.6, col=c[1] + 1.6, size=c[1] + 3.6)), text=[tx[20]]),
        dict(fn=S.zoom, args=dict(
            chain="chain_cols", kicker="From RTL to GDS", ttl="Bit lines meet standard cells",
            way=lambda c, D: [(0.5, 3), (c[0] + 7.5, 0)],
            overlays=lambda c, D: [(c[0] + 2.4, "clock-tree synthesis: phase clock → word-line gates → bit lines → crash", CHIP_BOX.format(880, 30, "#f85149", "#f85149"), c[2] - 0.3),
                                   (c[2] + 0.5, "fix: three hand-placed clock buffers in the Verilog", CHIP_BOX.format(880, 32, "#3fb950", "#3fb950"), None)]),
             text=[tx[21]]),
        dict(fn=S.signoff, args=dict(rows=chip_rows, kicker="From RTL to GDS", ttl="Sign-off of the complete memory",
                                     stamp=f"0 violations\n{R['lvs_devices']:,} devices\nmatch", q=lambda c, D: dict(start=0.6, span=c[2] + 0.6, stamp=c[2] + 1.4)),
             text=[tx[22]]),
        # ---- does it work?
        dict(fn=S.waves, args=dict(q=lambda c, D: dict(draw=0.8, drawdur=D - 5.0, tcq=D - 4.4)), text=[tx[23]]),
        dict(fn=S2.table, args=dict(q=lambda c, D: dict(head=0.6, rows=[c[0] + 1.6, c[1] + 1.4, c[1] + 5.6, c[2] + 0.4, c[2] + 2.2], note=c[0] + 3.6)), text=[tx[24]]),
        dict(fn=S.wrap, args=dict(items=["GDS, LEF, Liberty for three corners", "Verilog model and SPICE netlists", "March C- self-test, routed with the macro",
                                         "Every step reproducible from code"],
                                  warn=["No silicon: nothing has been fabricated or measured.", "Mismatch: only as good as the PDK's Monte Carlo models.",
                                        "No ECC or redundancy, no wire resistance inside the array."],
                                  q=lambda c, D: dict(items=c[1] + 0.2, istep=1.7, warn=c[2] + 0.2, wstep=1.8)),
             text=[tx[25]]),
        dict(fn=S2.lines, args=dict(items=[("Robust beats clever", "Full-swing bit lines and two clock phases remove a whole class of timing risks."),
                                           ("Design rules shape the circuit", "Without a foundry cell's special contacts, the cross-coupling wires decide the cell size."),
                                           ("Verify every level, then everything", "Cell, array and periphery on their own, and then the complete layout, flat.")],
                                    url=URL, q=lambda c, D: dict(items=[c[1], c[2], c[3]], url=c[4] + 0.2)),
             text=[tx[26]]),
    ]


SCRIPTS = {"short": short, "full": full}
